create or replace function public.generate_rent_charges(p_relationship_id uuid,p_through_date date default current_date) returns setof public.charges language plpgsql security definer set search_path='' as $$ declare r public.rental_relationships; v_month date; v_last_month date; v_period_start date; v_period_end date; v_due_date date; v_term public.rental_term_versions; v_created public.charges; v_days int; begin select * into r from public.rental_relationships where id=p_relationship_id for update; if not found then raise exception 'RENTAL_RELATIONSHIP_NOT_FOUND'; end if; if public.can_manage_administration(r.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if r.status not in('ACTIVE','ENDING','ENDED') then raise exception 'RENTAL_NOT_CHARGEABLE'; end if; if r.tracking_start_date is null or r.payment_day is null then raise exception 'RENTAL_BILLING_CONFIGURATION_INCOMPLETE'; end if; if p_through_date<r.tracking_start_date then return; end if; v_month:=date_trunc('month',r.tracking_start_date)::date; v_last_month:=date_trunc('month',least(p_through_date,coalesce(r.actual_end_date,p_through_date)))::date; while v_month<=v_last_month loop v_days:=extract(day from(v_month+interval '1 month'-interval '1 day'))::int; v_due_date:=v_month+(least(r.payment_day,v_days)-1); if v_due_date>=r.tracking_start_date then v_period_start:=greatest(v_month,r.tracking_start_date); v_period_end:=(v_month+interval '1 month'-interval '1 day')::date; if r.actual_end_date is not null then v_period_end:=least(v_period_end,r.actual_end_date); end if; select * into v_term from public.rental_term_versions t where t.rental_relationship_id=r.id and v_period_start between t.effective_from and coalesce(t.effective_until,'infinity'::date) order by t.version_number desc limit 1; if found then insert into public.charges(administration_id,rental_relationship_id,charge_type,origin,description,period_start,period_end,due_date,amount,currency,source_type,source_id) values(r.administration_id,r.id,'RENT','SYSTEM','Canon de arrendamiento',v_period_start,v_period_end,v_due_date,v_term.rent_amount,'COP','RENT_TERM_VERSION',v_term.id) on conflict do nothing returning * into v_created; if found then return next v_created; end if; end if; end if; v_month:=(v_month+interval '1 month')::date; end loop; return; end $$;